-// Wrap a raw COM pointer in a shared_ptr for auto Release().
-template <class T>
-std::shared_ptr<T> to_com_ptr(T* obj) {
-  return std::shared_ptr<T>(obj, [](T* p) {
-    if (p) {
-      p->Release();
-    }
-  });
-}
-
-}  // namespace
