-struct SimpleVertex {
-  DirectX::XMFLOAT3 pos;
-  DirectX::XMFLOAT2 tex;
-};
-
-Context::Context(ID3D11DeviceContext* ctx) : ctx_(to_com_ptr(ctx)) {}
-
-void Context::flush() {
-  ctx_->Flush();
