-  VERIFY_NO_ERROR;
-  glDrawArrays(GL_QUADS, 0, 4);
-  VERIFY_NO_ERROR;
-
-  // Disable 2D textures.
-  glDisable(GL_TEXTURE_2D);
-  VERIFY_NO_ERROR;
-
-  if (IsTransparent()) {
-    // Disable alpha blending.
-    glDisable(GL_BLEND);
-    VERIFY_NO_ERROR;
-  }
-
-  // Draw a rectangle around the update region.
-  if (settings_.show_update_rect && !update_rect_.IsEmpty()) {
-    int left = update_rect_.x;
-    int right = update_rect_.x + update_rect_.width;
-    int top = update_rect_.y;
-    int bottom = update_rect_.y + update_rect_.height;
-
-    // Shrink the box so that left & bottom sides are drawn.
-    left += 1;
-    bottom -= 1;
-
-    glPushAttrib(GL_ALL_ATTRIB_BITS);
-    VERIFY_NO_ERROR
-    glMatrixMode(GL_PROJECTION);
-    VERIFY_NO_ERROR;
-    glPushMatrix();
-    VERIFY_NO_ERROR;
-    glLoadIdentity();
-    VERIFY_NO_ERROR;
-    glOrtho(0, view_width_, view_height_, 0, 0, 1);
-    VERIFY_NO_ERROR;
-
-    glLineWidth(1);
-    VERIFY_NO_ERROR;
-    glColor3f(1.0f, 0.0f, 0.0f);
-    VERIFY_NO_ERROR;
-    // Don't check for errors until glEnd().
-    glBegin(GL_LINE_STRIP);
-    glVertex2i(left, top);
-    glVertex2i(right, top);
-    glVertex2i(right, bottom);
-    glVertex2i(left, bottom);
-    glVertex2i(left, top);
-    glEnd();
-    VERIFY_NO_ERROR;
-
-    glPopMatrix();
-    VERIFY_NO_ERROR;
-    glPopAttrib();
-    VERIFY_NO_ERROR;
-  }
