-    }
-  } else if (type == PET_POPUP && popup_rect_.width > 0 &&
-             popup_rect_.height > 0) {
-    int skip_pixels = 0, x = popup_rect_.x;
-    int skip_rows = 0, y = popup_rect_.y;
-    int w = width;
-    int h = height;
